function chartLine(){let terms=[...db.terms].reverse(),avg=terms.map(t=>weightedMean(resultsForTerm(t.id)));let w=500,h=200,l=32,r=15,top=13,bottom=26,pts=avg.map((v,i)=>[l+i*(w-l-r)/Math.max(1,avg.length-1),top+(100-v)*(h-top-bottom)/100]);let path=pts.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' '), area=`${path} L${pts.at(-1)?.[0]||l},${h-bottom} L${pts[0]?.[0]||l},${h-bottom} Z`;return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Average percentage by term"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#7779ed" stop-opacity=".22"/><stop offset="1" stop-color="#7779ed" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(v=>{let y=top+(100-v)*(h-top-bottom)/100;return `<line class="gridline" x1="${l}" x2="${w-r}" y1="${y}" y2="${y}"/><text x="1" y="${y+3}">${v}%</text>`}).join('')}<path class="area" d="${area}"/><path class="line" d="${path}"/>${pts.map((p,i)=>`<circle class="point" cx="${p[0]}" cy="${p[1]}" r="4"><title>${esc(terms[i]?.name)} ${avg[i].toFixed(1)}%</title></circle><text text-anchor="middle" x="${p[0]}" y="${h-7}">${esc(terms[i]?.name?.split(' ')[0]||'')}</text>`).join('')}</svg>`}
