function studentsPage(){let q=(filters.q||'').toLowerCase(),list=db.students.filter(s=>`${s.name} ${s.id} ${s.class_name}`.toLowerCase().includes(q));return `${pageHead('Student directory','Manage student records and open an individual academic report.',`<button class="btn" data-export>↓ Export results</button><button class="btn primary" data-modal="student">＋ Add student</button>`)}<div class="card table-card reveal"><div class="table-toolbar"><div class="search"><input id="student-search" placeholder="Search name, student ID or class…" value="${esc(filters.q)}"></div><select class="filter-select" id="student-class"><option value="">All classes</option>${classes().map(c=>`<option ${filters.class===c?'selected':''}>${esc(c)}</option>`).join('')}</select><span style="font-size:9px;color:#939dad">${list.filter(s=>!filters.class||s.class_name===filters.class).length} students</span></div><div class="table-scroll"><table><thead><tr><th>Student</th><th>Student ID</th><th>Class</th><th>Roll</th><th>Email</th><th>Average</th><th></th></tr></thead><tbody>${list.filter(s=>!filters.class||s.class_name===filters.class).map(s=>{let rr=db.results.filter(r=>r.student_id===s.id),avg=weightedMean(rr);return `<tr><td><div class="student-cell"><span class="mini-avatar">${initials(s.name)}</span><span><b>${esc(s.name)}</b><small>Active student</small></span></div></td><td>${esc(s.id)}</td><td>${esc(s.class_name)}</td><td>${esc(s.roll)}</td><td>${esc(s.email||'—')}</td><td>${avg.toFixed(1)}%</td><td><button class="btn small" data-report="${s.id}">Report card →</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No students found.</td></tr>'}</tbody></table></div></div>`}
function overallRanking(rows,cls=''){let students=db.students.filter(s=>!cls||s.class_name===cls).map(s=>{let marks=rows.filter(r=>r.student_id===s.id),subjects=new Set(marks.map(r=>r.subject_id)).size,total=marks.reduce((a,r)=>a+Number(r.score),0),max=marks.reduce((a,r)=>a+Number(r.max_marks),0),average=marks.length?marks.reduce((a,r)=>a+Number(r.percentage),0)/marks.length:0;return {student:s,marks,subjects,total,max,average,complete:db.subjects.length>0&&subjects===db.subjects.length}}),complete=students.filter(s=>s.complete).sort((a,b)=>b.average-a.average||b.total-a.total||a.student.name.localeCompare(b.student.name)),last=null,rank=0;complete.forEach((s,i)=>{let score=s.average.toFixed(1);if(score!==last){rank=i+1;last=score}s.rank=rank});return {ranked:complete,incomplete:students.filter(s=>!s.complete).sort((a,b)=>a.student.name.localeCompare(b.student.name)),students}}
