function renderReport(sid){if(role==='Student'&&db.workflow?.[String(termId())]!=='Published'){$('#report-area').innerHTML='<div class="notice warn">Your report will appear here after an administrator publishes results for this term.</div>';return}let s=db.students.find(x=>x.id===sid);if(!s)return;let rr=db.results.filter(r=>r.student_id===sid),avg=weightedMean(rr),passed=rr.filter(r=>r.passed).length,total=rr.reduce((a,r)=>a+Number(r.score),0),maxTotal=rr.reduce((a,r)=>a+Number(r.max_marks),0),gpa=rr.length?rr.reduce((a,r)=>a+r.gpa*(Number(r.weight)||1),0)/rr.reduce((a,r)=>a+(Number(r.weight)||1),0):0;$('#report-area').innerHTML=`<div class="result-card"><div class="report-logo"><span>✳</span> meridian</div><div class="report-meta">Academic report · ${esc(db.terms.find(t=>String(t.id)===String(termId()))?.name||'')}</div><div class="report-student"><h2>${esc(s.name)}</h2><p>${esc(s.class_name)} &nbsp;·&nbsp; Student ${esc(s.id)} &nbsp;·&nbsp; Roll ${esc(s.roll)}</p></div><div class="report-score"><strong>${avg.toFixed(1)}%</strong><div><span>Weighted mean</span><small>${total} / ${maxTotal} marks · ${passed} of ${rr.length} subjects passed</small></div></div></div><div style="margin:14px 0 8px" class="card-title">Subject performance</div>${miniResultsTable(rr)}<p style="font-size:9px;color:#9aa3b1;margin:11px 2px">Grade is based on each subject's configured maximum and pass mark. ${rr.length?'Weighted GPA estimate: '+gpa.toFixed(2)+' / 4.00.':''}</p>`}
