function bindImport(){let input=$('#csv-file'),dz=$('#dropzone');$('#choose-file').onclick=()=>input.click();input.onchange=()=>readCSV(input.files[0]);dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag')};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag');readCSV(e.dataTransfer.files[0])}}
async function readCSV(file){if(!file)return;if(!file.name.toLowerCase().endsWith('.csv')){toast('Choose a .csv file');return}let txt=await file.text(),headers=(txt.split(/\r?\n/)[0]||'').split(',').map(x=>x.trim().replace(/^"|"$/g,''));let guess=(terms)=>headers.find(h=>terms.includes(h.toLowerCase()))||headers[0]||'';let mapping={student:guess(['student_id','student id','student','id']),subject:guess(['subject_code','subject code','subject']),term:guess(['term','semester']),score:guess(['score','marks','mark'])};$('#st1').classList.add('done');$('#st2').classList.add('active');$('#mapping-area').innerHTML=`<div class="card-title" style="margin-bottom:5px">Map your columns</div><div class="card-sub" style="margin-bottom:12px">Choose which CSV column contains each field. We recognize common column names.</div><div class="mapping-grid">${Object.entries(mapping).map(([k,v])=>`<div class="field"><label>${k[0].toUpperCase()+k.slice(1)}</label><select data-map="${k}">${headers.map(h=>`<option ${h===v?'selected':''}>${esc(h)}</option>`).join('')}</select></div>`).join('')}</div><button class="btn primary" id="validate-import" style="margin-top:14px">Validate file →</button><div id="preview-area"></div>`;$('#validate-import').onclick=async()=>{mapping=Object.fromEntries($$('[data-map]').map(x=>[x.dataset.map,x.value]));try{let preview=await post('/api/import/preview',{csv:txt,mapping});importRows=preview.rows;$('#st2').classList.add('done');$('#st3').classList.add('active');$('#preview-area').innerHTML=`<div class="notice ${preview.errors?'warn':''}" style="margin-top:15px">${preview.valid} rows ready to import · ${preview.errors} row errors. Existing rows flagged for update are valid.</div><div class="table-scroll" style="margin-top:10px;max-height:340px"><table><thead><tr><th>Line</th><th>Student</th><th>Subject</th><th>Term</th><th>Score</th><th>Validation</th></tr></thead><tbody>${preview.rows.map(r=>`<tr><td>${r.line}</td><td>${esc(r.student)}</td><td>${esc(r.subject)}</td><td>${esc(r.term)}</td><td>${esc(r.score)}</td><td>${r.errors.length?`<span class="status ${r.valid?'review':''}">${esc(r.errors.join('; '))}</span>`:'<span class="status pass">Ready</span>'}</td></tr>`).join('')}</tbody></table></div><button class="btn primary" id="commit-import" ${preview.valid?'':'disabled'} style="margin-top:12px">Import ${preview.valid} valid rows</button>`;$('#commit-import').onclick=async()=>{try{let r=await post('/api/import/commit',{rows:importRows});toast(`${r.count} marks imported`);navigate('results');await load()}catch(e){toast(e.message)}}}catch(e){toast(e.message)}}}
