$('#role-select').onchange=e=>{role=e.target.value;draw();toast(`Switched to ${role} view`)};
$('#notification-btn').onclick=()=>{let notes=[],state=db.workflow?.[String(termId())]||'Draft';if(state==='Submitted for review')notes.push(['Awaiting review','A result set has been submitted for administrator review.']);let incomplete=db.students.length*db.subjects.length-db.results.length;if(incomplete>0)notes.push(['Incomplete marks',`${incomplete} student-subject marks are missing for this term.`]);if(state==='Published')notes.push(['Results published','Published results are available in report cards.']);showModalHtml(`<h2>Notifications</h2><p>Actionable items for the selected academic term.</p><div class="notification-list">${notes.length?notes.map(n=>`<div class="notification"><span class="n-icon">!</span><div><b>${esc(n[0])}</b><p>${esc(n[1])}</p></div></div>`).join(''):'<div class="empty">You’re all caught up.</div>'}</div>`)};
$('#help-btn').onclick=()=>showModalHtml(`<h2>Meridian quick guide</h2><p>Import marks from CSV, review calculated results, and publish the approved term set. Student records and marks stay in this local workspace database.</p><div class="stat-row"><span>CSV template</span><a href="/api/template"><b>Download</b></a></div><div class="stat-row"><span>Teacher role</span><b>Submit / return</b></div><div class="stat-row"><span>Administrator role</span><b>Approve / publish</b></div>`);
$('#rules-info').onclick=openGradingRulesModal;
function showModalHtml(html){$('#modal-content').innerHTML=html;$('#modal').hidden=false}
$('#modal-close').onclick=()=>$('#modal').hidden=true;$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').hidden=true};$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');
load();
function activityCard(){let rows=(db.events||[]).slice(0,30);return `<div class="card reveal" style="margin-top:15px"><div class="card-head"><div><div class="card-title">Audit trail</div><div class="card-sub">Recent imports, record changes, approvals, and publications</div></div><span class="status draft">LOCAL HISTORY</span></div><div class="table-scroll" style="max-height:300px"><table><thead><tr><th>When</th><th>Actor</th><th>Action</th><th>Details</th></tr></thead><tbody>${rows.length?rows.map(e=>`<tr><td>${esc(new Date(e.at).toLocaleString())}</td><td>${esc(e.actor)}</td><td><b>${esc(e.action)}</b></td><td>${esc(e.detail)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No recorded activity yet.</td></tr>'}</tbody></table></div></div>`}
function openGradingRulesModal(){let r=rules(),bands=['A*','A','B','C','D'];let values=bands.map(g=>`<div class="field"><label for="band-${g.replace('*','star')}">${g} minimum percentage</label><input id="band-${g.replace('*','star')}" name="${g}" type="number" min="0" max="100" step="1" value="${r[g]}" required></div>`).join('');showModalHtml(`<h2>Grading rules</h2><p>Grade bands are based on percentage of the subject maximum. E is the subject pass mark below the D threshold; U is below the subject pass mark.</p><div class="stat-row"><span>Pass status</span><b>Raw score ≥ subject pass mark</b></div>${role==='Administrator'?`<form id="grade-rule-form" class="modal-form"><div class="form-grid">${values}</div><div class="notice" style="margin-top:12px">Thresholds must descend from A* to D. Changes recalculate grades across all terms and are saved to this local database.</div><div class="modal-actions"><button type="button" class="btn" id="cancel-modal">Cancel</button><button class="btn primary">Save grading rules</button></div></form>`:`<div class="grade-bars" style="margin-top:15px">${bands.map(g=>`<div class="stat-row"><span>${g}</span><b>${r[g]}% and above</b></div>`).join('')}<div class="stat-row"><span>E / U</span><b>At pass mark / below pass</b></div></div>`}`);$('#cancel-modal')?.addEventListener('click',()=>$('#modal').hidden=true);$('#grade-rule-form')?.addEventListener('submit',async e=>{e.preventDefault();try{let raw=Object.fromEntries(new FormData(e.currentTarget));await post('/api/grading-rules',{rules:raw});$('#modal').hidden=true;toast('Grading rules saved');await load()}catch(err){toast(err.message)}})}
function classComparisonCard(){let rows=currentResults(), stats=classes().filter(c=>!filters.class||c===filters.class).map(c=>{let a=rows.filter(r=>r.class_name===c);return {name:c,count:new Set(a.map(x=>x.student_id)).size,mean:weightedMean(a),pass:a.length?a.filter(x=>x.passed).length/a.length*100:0}});return `<div class="card reveal" style="margin-top:15px"><div class="card-head"><div><div class="card-title">Class comparison</div><div class="card-sub">Weighted mean, pass rate, and learners represented · selected term</div></div></div><div class="table-scroll"><table><thead><tr><th>Class</th><th>Students</th><th>Mean</th><th>Pass rate</th></tr></thead><tbody>${stats.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.count}</td><td>${x.mean.toFixed(1)}%</td><td>${x.pass.toFixed(0)}%</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No class records in this filter.</td></tr>'}</tbody></table></div></div>`}
function addStudentEditButtons(){$$('[data-report]').forEach(b=>{let edit=document.createElement('button');edit.className='btn small';edit.textContent='Edit';edit.dataset.editStudent=b.dataset.report;edit.style.marginRight='5px';b.before(edit)})}
function addSubjectEditButtons(){let table=$('#page table');if(!table)return;let head=document.createElement('th');head.textContent='Actions';table.querySelector('thead tr').append(head);[...table.querySelectorAll('tbody tr')].forEach((tr,i)=>{let sub=[...db.subjects].sort((a,b)=>a.name.localeCompare(b.name))[i];if(!sub)return;let td=document.createElement('td'),btn=document.createElement('button');btn.className='btn small';btn.textContent='Edit';btn.dataset.editSubject=sub.id;td.append(btn);tr.append(td)})}
function openEditModal(kind,id){let item=kind==='student'?db.students.find(x=>x.id===id):db.subjects.find(x=>x.id===id);if(!item)return;let title=kind==='student'?'Edit student':'Edit subject',fields=kind==='student'?`<div class="form-grid"><div class="field"><label>Student ID</label><input value="${esc(item.id)}" disabled><input name="id" type="hidden" value="${esc(item.id)}"></div><div class="field"><label>Full name *</label><input name="name" value="${esc(item.name)}" required></div><div class="field"><label>Class *</label><input name="class_name" value="${esc(item.class_name)}" required></div><div class="field"><label>Roll number *</label><input name="roll" value="${esc(item.roll)}" required></div><div class="field full"><label>Email</label><input name="email" type="email" value="${esc(item.email)}"></div></div>`:`<div class="form-grid"><input name="id" type="hidden" value="${esc(item.id)}"><div class="field"><label>Subject name *</label><input name="name" value="${esc(item.name)}" required></div><div class="field"><label>Subject code *</label><input name="code" value="${esc(item.code)}" required></div><div class="field"><label>Maximum marks</label><input name="max_marks" type="number" min="1" value="${item.max_marks}"></div><div class="field"><label>Pass mark</label><input name="pass_mark" type="number" min="0" value="${item.pass_mark}"></div><div class="field"><label>Weight</label><input name="weight" type="number" min=".1" step=".1" value="${item.weight}"></div></div>`;$('#modal-content').innerHTML=`<h2>${title}</h2><p>Changes are saved locally and recorded in the audit trail.</p><form id="edit-form" class="modal-form">${fields}<div class="modal-actions"><button type="button" class="btn" id="cancel-modal">Cancel</button><button class="btn primary">Save changes</button></div></form>`;$('#modal').hidden=false;$('#cancel-modal').onclick=()=>$('#modal').hidden=true;$('#edit-form').onsubmit=async e=>{e.preventDefault();try{await post(kind==='student'?'/api/students/update':'/api/subjects/update',Object.fromEntries(new FormData(e.currentTarget)));$('#modal').hidden=true;toast('Changes saved');await load()}catch(err){toast(err.message)}}}
document.addEventListener('click',e=>{let s=e.target.closest('[data-edit-student]'),sub=e.target.closest('[data-edit-subject]');if(s)openEditModal('student',s.dataset.editStudent);if(sub)openEditModal('subject',sub.dataset.editSubject)});
